FILE: app/src/limited-orbit.ts
```ts
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";
import { attachControl, setCameraLimits } from "@babylonjs/lite";

export function attachLimitedOrbit(
  camera: ArcRotateCamera,
  canvas: HTMLCanvasElement,
  scene: SceneContext,
  minDistance: number,
  maxDistance: number
): () => void {
  const disposeControl = attachControl(camera, canvas, scene);
  const disposeLimits = setCameraLimits(
    camera,
    { lowerRadiusLimit: minDistance, upperRadiusLimit: maxDistance },
    scene
  );

  return () => {
    disposeControl();
    disposeLimits();
  };
}
```

I wired up `attachControl` for the standard orbit/zoom/pinch interactions and `setCameraLimits` to clamp `radius` on every write (and immediately clamp the current pose if it starts out of range); the returned function disposes both so no canvas listeners or per-frame hooks remain. I'm confident in this approach based on the notes (especially 2, 29, and 62), though I'm slightly uncertain whether `setCameraLimits` needs the `scene` argument for the clamping hook itself — I pass it anyway since the signature allows it and it costs nothing.
